import { test, expect } from '@playwright/test';

test.describe('Search Field Dropdown Options', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should display dropdown with matching options when typing in search field', async ({ page }) => {
    // Locate the search input field
    const searchInput = page.getByRole('searchbox');

    // Type in the search field
    await searchInput.fill('apple');

    // Wait for dropdown to appear
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Verify matching options are displayed
    const options = page.getByRole('option');
    await expect(options).toHaveCount(3);

    // Verify options contain the search term
    const firstOption = page.getByRole('option').first();
    await expect(firstOption).toContainText('apple');
  });

  test('should filter dropdown options based on search input', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Type initial search term
    await searchInput.fill('ban');

    // Verify dropdown appears with filtered results
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Check that only matching options are shown
    const options = page.getByRole('option');
    const optionCount = await options.count();
    expect(optionCount).toBeGreaterThan(0);

    // Verify first option matches the search term
    const firstOption = options.first();
    const optionText = await firstOption.textContent();
    expect(optionText?.toLowerCase()).toContain('ban');
  });

  test('should clear dropdown when search field is emptied', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Type in search field
    await searchInput.fill('orange');

    // Verify dropdown is visible
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Clear the search field
    await searchInput.clear();

    // Verify dropdown is hidden or empty
    await expect(dropdown).not.toBeVisible();
  });

  test('should select option from dropdown and populate search field', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Type to trigger dropdown
    await searchInput.fill('gra');

    // Wait for dropdown to appear
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Click on first option
    const firstOption = page.getByRole('option').first();
    await firstOption.click();

    // Verify search field is populated with selected option
    const selectedValue = await searchInput.inputValue();
    expect(selectedValue.length).toBeGreaterThan(0);

    // Verify dropdown is closed after selection
    await expect(dropdown).not.toBeVisible();
  });

  test('should display no results message when no options match search term', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Type a search term that has no matches
    await searchInput.fill('xyz123notfound');

    // Check for no results message
    const noResultsMessage = page.getByText(/no results|no matching/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify dropdown is still visible but empty
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    const options = page.getByRole('option');
    await expect(options).toHaveCount(0);
  });

  test('should navigate dropdown options using keyboard arrows', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Type to trigger dropdown
    await searchInput.fill('p');

    // Wait for dropdown
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Press arrow down to navigate
    await searchInput.press('ArrowDown');

    // Verify first option is highlighted
    const firstOption = page.getByRole('option').first();
    await expect(firstOption).toBeFocused();

    // Press arrow down again
    await searchInput.press('ArrowDown');

    // Verify second option is highlighted
    const secondOption = page.getByRole('option').nth(1);
    await expect(secondOption).toBeFocused();
  });
});
